/*! noble-hashes - MIT License (c) 2022 Paul Miller (paulmillr.com) */

const salt = Uint8Array.fromBase64("uBkfmHtaYE2PfnqZ9YTUiQ==")
const button = document.querySelector(".translate-button")
const input = document.querySelector(".password-input")
button.addEventListener("click", () => translate(document.querySelector(".decode"), input.value), {once: true})

async function translate(encoded_div, password){
    const trimmed_text = Uint8Array.fromBase64(encoded_div.textContent.trim())
    const nonce = trimmed_text.subarray(0, 12)
    const encoded_text = trimmed_text.subarray(12)

    const key = await nobleHashes.scryptAsync(password, salt, { N: 65536, r: 8, p: 1, dkLen: 32 });

    const {gcm, utils} = nobleCiphers;
    const cipher = gcm(key, nonce);
    const bytes = cipher.decrypt(encoded_text)
    const decoded_text = new TextDecoder().decode(bytes);

    encoded_div.textContent = decoded_text
}